def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    plane_patches = image_patch.find("plane")
    if len(plane_patches) < 4:
        return image_patch

    # Sort planes by their vertical center
    plane_patches.sort(key=lambda p: p.vertical_center)

    # Find pairs of identical planes
    identical_pairs = []
    i = 0
    while i < len(plane_patches) - 1:
        if plane_patches[i].cropped_image.shape == plane_patches[i + 1].cropped_image.shape:
            identical_pairs.append((plane_patches[i], plane_patches[i + 1]))
            i += 2
        else:
            i += 1

    # Check for pairs of identical planes between other identical planes
    for pair in identical_pairs:
        prev_plane = next((p for p in plane_patches if p != pair[0] and p != pair[1]), None)
        next_plane = next((p for p in plane_patches if p != pair[0] and p != pair[1]), None)

        if prev_plane and next_plane:
            if is_between_3d(prev_plane, pair[0], pair[1]) and is_between_3d(pair[1], next_plane, prev_plane):
                return pair[0]

    return image_patch

