def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    chairs = image_patch.find("chair")
    windows = image_patch.find("window")

    if not chairs or not windows:
        return image_patch

    empty_chairs = [c for c in chairs if not c.verify_property("chair", "occupied")]

    if not empty_chairs:
        return image_patch

    closest_window = min(windows, key=lambda w: distance(empty_chairs[0], w))

    inside_chairs = [c for c in empty_chairs if c.overlaps_with(closest_window.left, closest_window.lower, closest_window.right, closest_window.upper)]

    if not inside_chairs:
        return empty_chairs[0]

    return min(inside_chairs, key=lambda c: abs(c.horizontal_center - closest_window.horizontal_center))

