def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    zebra_patches = image_patch.find("zebra")
    water_patches = image_patch.find("water")

    if not zebra_patches or not water_patches:
        return image_patch

    min_distance = float('inf')
    closest_zebra = None

    for zebra in zebra_patches:
        for water in water_patches:
            dist = abs(zebra.horizontal_center - water.horizontal_center)
            if dist < min_distance:
                min_distance = dist
                closest_zebra = zebra

    return closest_zebra

