    image_patch = ImagePatch(image)
    horse_patches = image_patch.find("horse")
    cycle_patches = image_patch.find("cycle")

    if not horse_patches or not cycle_patches:
        return image_patch

    best_horse = None
    best_match_ratio = -1

    for horse in horse_patches:
        for cycle in cycle_patches:
            if horse.overlaps_with(cycle.left, cycle.lower, cycle.right, cycle.upper):
                match_ratio = (horse.right - horse.left) * (horse.upper - horse.lower) / ((cycle.right - cycle.left) * (cycle.upper - cycle.lower))
                if match_ratio > best_match_ratio:
                    best_match_ratio = match_ratio
                    best_horse = horse

    return best_horse if best_horse else horse_patches[0]

legacy_c5_q7.program:
def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    horses = image_patch.find("horse")
    cycles = image_patch.find("cycles")

    if not horses or not cycles:
        return image_patch

    horse_centers = [(h.left + h.right) / 2 for h in horses]
    cycle_centers = [(c.left + c.right) / 2 for c in cycles]

    for horse in horses:
        for cycle in cycles:
            if abs(horse_centers[horses.index(h)] - cycle_centers[cycles.index(c)]) < 10:
                return horse

    return horses[0]

