def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    umbrella_patches = image_patch.find("umbrella")
    woman_patches = image_patch.find("woman")

    if not umbrella_patches or not woman_patches:
        return image_patch

    woman = woman_patches[0]
    closest_umbrella = None
    min_distance = float('inf')

    for umbrella in umbrella_patches:
        if umbrella.verify_property("umbrella", "green") and umbrella.verify_property("umbrella", "striped"):
            distance_to_woman = abs(umbrella.horizontal_center - woman.horizontal_center)
            if distance_to_woman < min_distance:
                min_distance = distance_to_woman
                closest_umbrella = umbrella

    return closest_umbrella

