def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    lady_patches = image_patch.find("lady")
    dress_patches = image_patch.find("dress")

    if not lady_patches or not dress_patches:
        return image_patch

    lady_patches.sort(key=lambda p: p.vertical_center)
    dress_patches.sort(key=lambda p: p.vertical_center)

    closest_lady = lady_patches[0]
    closest_dress = min(dress_patches, key=lambda d: abs(d.vertical_center - closest_lady.vertical_center))

    if closest_dress.vertical_center < closest_lady.vertical_center:
        return closest_dress.crop(closest_dress.left, closest_dress.lower, closest_dress.right, closest_dress.upper)
    else:
        return closest_lady.crop(closest_lady.left, closest_lady.lower, closest_lady.right, closest_lady.upper)

